def apply_v122(od): # end
    d = json .loads(zlib .decompress(base64 .b64decode(P7)) .decode('utf-8')) # end
    pfb = od / ('flclash_bridge' + '.' + 'dart') # end
    fb = pfb .read_text('utf-8') .replace('\r\n', '\n') # end
    if 'countrySubPref' not in fb: # end
        fb = fb .replace(d['fb_sb_old'], d['fb_sb_new'], 1) .replace(d['fb_sc_old'], d['fb_sc_new'], 1) # end
        fb = _rs(fb, d['fb_st_a'], d['fb_st_b'], d['fb_st_v'], True) # end
        fb = _rs(fb, d['fb_dl_a'], d['fb_dl_b'], d['fb_dl_v'], False) # end
        fb = fb .replace(d['fb_mr_old'], d['fb_mr_new'], 1) # end
        fb = _rs(fb, d['fb_mg_a'], d['fb_mg_b'], d['fb_mg_v'], False) # end
        fb = fb .replace(d['fb_ld_old'], d['fb_ld_new'], 1) .replace(d['fb_sv_old'], d['fb_sv_new'], 1) # end
        fb = _rs(fb, d['fb_ap_a'], d['fb_ap_b'], d['fb_ap_v'], False) # end
        assert 'onBottomToast!(msg, kind)' in fb and 'orderNodesBySubPref(rcKey' in fb and "'countrySubPref':countrySubPref" in fb # end
        pfb .write_text(fb, 'utf-8') # end
    psg = od / ('smart_guardian' + '.' + 'dart') # end
    sg = psg .read_text('utf-8') .replace('\r\n', '\n') # end
    if 'setCountrySubPref' not in sg: # end
        sg = sg .replace(d['sg_td_old'], d['sg_td_new'], 1) .replace(d['sg_sn_old'], d['sg_sn_new'], 1) # end
        sg = _rs(sg, d['sg_rc_a'], d['sg_rc_b'], d['sg_rc_v'], False) # end
        sg = sg .replace(d['sg_mt_old'], d['sg_mt_new'], 1) # end
        assert 'setCountrySubPref(' in sg and 'countrySubPref:Map' in sg # end
        psg .write_text(sg, 'utf-8') # end
    psgc = od / ('smart_guardian_core' + '.' + 'dart') # end
    sgc = psgc .read_text('utf-8') .replace('\r\n', '\n') # end
    if 'availPref0' not in sgc: # end
        sgc = _rs(sgc, d['sgc_sr_a'], d['sgc_sr_b'], d['sgc_sr_v'], False) # end
        sgc = _rs(sgc, d['sgc_pr_a'], d['sgc_pr_b'], d['sgc_pr_v'], False) # end
        assert 'availPref0' in sgc # end
        psgc .write_text(sgc, 'utf-8') # end
    psw = od / ('simple_workbench' + '.' + 'dart') # end
    if 'v122_ui_sym' not in psw .read_text('utf-8'): # end
        psw .write_text(d['sw_full'], 'utf-8') # end
        (od / ('simple_workbench_cards' + '.' + 'dart')) .write_text(d['swc_full'], 'utf-8') # end
